#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"

#include <chrono>
#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// RibbonToolTip's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/ribbon_tool_tip.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// How long the pointer rests before a tooltip shows. A negative delay throws std::invalid_argument.
template <typename Declaring>
struct RibbonToolTipInitialDelayCapability {
    PropertyCell<std::chrono::milliseconds, RibbonToolTipInitialDelayCapability<Declaring>> initial_delay{500};

    static void assign(RibbonToolTipInitialDelayCapability& capability, std::chrono::milliseconds incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.initial_delay), incoming);
        if (!capability.initial_delay.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.initial_delay));
    }
};

// How long a tooltip stays without input; zero keeps it until the pointer leaves or focus moves. A negative delay throws std::invalid_argument.
template <typename Declaring>
struct RibbonToolTipAutoPopDelayCapability {
    PropertyCell<std::chrono::milliseconds, RibbonToolTipAutoPopDelayCapability<Declaring>> auto_pop_delay{10000};

    static void assign(RibbonToolTipAutoPopDelayCapability& capability, std::chrono::milliseconds incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.auto_pop_delay), incoming);
        if (!capability.auto_pop_delay.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.auto_pop_delay));
    }
};

// The line a tooltip with a help topic shows under a rule. Text that is not valid UTF-8 throws std::invalid_argument.
template <typename Declaring>
struct RibbonToolTipHelpLineTextCapability {
    PropertyCell<std::string, RibbonToolTipHelpLineTextCapability<Declaring>> help_line_text{"Press F1 for more help."};

    static void assign(RibbonToolTipHelpLineTextCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.help_line_text), incoming);
        if (!capability.help_line_text.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.help_line_text));
    }
};

// Every RibbonToolTip capability, in the order the declaring class takes them.
template <typename Declaring>
struct RibbonToolTipCapabilities : public RibbonToolTipInitialDelayCapability<Declaring>,
                                   public RibbonToolTipAutoPopDelayCapability<Declaring>,
                                   public RibbonToolTipHelpLineTextCapability<Declaring> {};

} // namespace gui_forms
